@startuml

class WebPortal {
  +versionNumber : string
  +urlAddress : string
}

class Building {
  +id : string
  +name : string
  +energyClass : string
  +address : string
  +yearOfConstruction : int
}

class AdditionalEntry {
  +name : string
}

class TextualInformation extends AdditionalEntry {}

class NumericalInformation extends AdditionalEntry {
  +value : float
  +unit : string
}

class Image {
  +fileName : string
}

class User {
  +userName : string
  +emailAddress : string
  +password : string
}

class Administrator extends User {
  +idCardNumber : string
}

class Comment {
}

class Visitor {
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "0..1" -- "*" User : registers
WebPortal "0..1" -- "*" Visitor : allows access to

Building "1" *-- "*" AdditionalEntry : has
Building "1" *-- "*" Image : has
Building "0..1" -- "1" Image : profile photo

User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
User "1" -- "*" AdditionalEntry : manages
User "1" -- "*" Building : creates

Administrator "1" -- "*" User : sets up
Administrator "1" -- "*" Comment : deletes

Visitor "0..1" -- "*" AdditionalEntry : can view public
Visitor "1" -- "*" Building : searches

@enduml

